#!/usr/bin/env python3
"""Run an AIDE JSON check and atomically spool normalized NDJSON for Splunk."""
import datetime
import hashlib
import json
import os
import subprocess
import sys
import time
import uuid

AIDE = "/usr/sbin/aide"
CONFIG = "/etc/aide-etc.conf"
DATABASE = "/var/lib/aide/aide.db.gz"
SPOOL = "/var/lib/splunk-etc-fim/spool"
SCHEMA_VERSION = 1
SAFE_ENV = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LANG": "C", "LC_ALL": "C"}


def utc(epoch):
    return datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            block = handle.read(1048576)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def bounded(value, limit=1024):
    text = str(value)
    return text if len(text) <= limit else text[:limit] + "..."


def write_atomic(scan_id, events):
    os.makedirs(SPOOL, mode=0o750, exist_ok=True)
    temporary = os.path.join(SPOOL, "." + scan_id + ".tmp")
    final = os.path.join(SPOOL, scan_id + ".ndjson")
    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC | os.O_NOFOLLOW, 0o640)
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        for event in events:
            handle.write(json.dumps(event, separators=(",", ":"), sort_keys=True) + "\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, final)


def main():
    scan_epoch = int(time.time())
    scan_id = str(uuid.uuid4())
    base = {"event_time": utc(scan_epoch), "schema_version": SCHEMA_VERSION, "scan_id": scan_id, "scan_epoch": scan_epoch}
    events = []
    try:
        config_hash = sha256(CONFIG)
        database_hash = sha256(DATABASE)
        completed = subprocess.run([AIDE, "--check", "--config", CONFIG], check=False, capture_output=True, text=True, timeout=14400, env=SAFE_ENV)
        if completed.returncode < 0 or completed.returncode > 7:
            raise RuntimeError("aide_error_exit=" + str(completed.returncode) + "; stderr=" + bounded(completed.stderr))
        report = json.loads(completed.stdout)
        if not isinstance(report, dict):
            raise ValueError("AIDE JSON report is not an object")
        groups = {}
        for change_type in ("added", "removed", "changed"):
            value = report.get(change_type) or {}
            if not isinstance(value, dict):
                raise ValueError("AIDE report group is not an object: " + change_type)
            groups[change_type] = value
        expected_exit = (1 if groups["added"] else 0) + (2 if groups["removed"] else 0) + (4 if groups["changed"] else 0)
        if completed.returncode != expected_exit:
            raise ValueError("AIDE exit/report mismatch: exit=" + str(completed.returncode) + " report_bits=" + str(expected_exit))
        details = report.get("details") or {}
        if not isinstance(details, dict):
            details = {}
        aide_version = bounded(report.get("aide_version", "unknown"), 128)
        for change_type, paths in groups.items():
            for path, vector in paths.items():
                path_details = details.get(path) or {}
                if not isinstance(path_details, dict):
                    path_details = {"unparsed_details": bounded(path_details)}
                event = dict(base)
                event.update(record_type="fim_change", collector_status="ok", aide_version=aide_version, aide_exit_code=completed.returncode, change_type=change_type, path=path, change_vector=bounded(vector, 256), changed_attributes=sorted(path_details.keys()), details=path_details, database_sha256=database_hash, config_sha256=config_hash)
                events.append(event)
        terminal = dict(base)
        terminal.update(record_type="scan_complete", collector_status="ok", collector_error=None, aide_version=aide_version, aide_exit_code=completed.returncode, added_count=len(groups["added"]), removed_count=len(groups["removed"]), changed_count=len(groups["changed"]), database_sha256=database_hash, config_sha256=config_hash, completed_epoch=int(time.time()))
        events.append(terminal)
        write_atomic(scan_id, events)
        return 0
    except Exception as error:
        terminal = dict(base)
        terminal.update(record_type="scan_complete", collector_status="error", collector_error=type(error).__name__ + ": " + bounded(error), aide_version=None, aide_exit_code=None, added_count=None, removed_count=None, changed_count=None, database_sha256=None, config_sha256=None, completed_epoch=int(time.time()))
        write_atomic(scan_id, [terminal])
        return 1


if __name__ == "__main__":
    sys.exit(main())
